#!/usr/bin/env python3
"""Build data/public_figures.txt from public Wikidata SPARQL (no key).
One name per line (labels + selected aliases). Run manually / at build; output is committed so the
site never depends on Wikidata being up. Public figures may be watched as KEYWORDS (news/post text only)
and are not masked. Never used for location tracking."""
import json,urllib.request,urllib.parse,re,sys,time,os
EP='https://query.wikidata.org/sparql'
UA='EyemontPublicFigures/1.0 (https://github.com/SinDistrictMayor/eyemont)'
def q(s):
  for a in range(3):
    try:
      r=urllib.request.Request(EP+'?'+urllib.parse.urlencode({'query':s,'format':'json'}),headers={'User-Agent':UA})
      return json.load(urllib.request.urlopen(r,timeout=70))['results']['bindings']
    except Exception as e: print('retry',e,file=sys.stderr);time.sleep(5)
  return []
POS=lambda cls,since: f"""SELECT DISTINCT ?l WHERE {{ ?p p:P39 ?st. ?st ps:P39 ?pos. ?pos wdt:P279* wd:{cls}. ?p wikibase:sitelinks ?n. FILTER(?n>=12)
 OPTIONAL{{?st pq:P582 ?end}} FILTER(!BOUND(?end) || ?end > "{since}-01-01"^^xsd:dateTime)
 ?p wdt:P31 wd:Q5; rdfs:label ?l. FILTER(LANG(?l)="en") }}"""
QS={
 'heads of state':POS('Q48352',2010),
 'heads of government':POS('Q2285706',2010),
 'ministers':"""SELECT DISTINCT ?l WHERE { ?p p:P39 ?st. ?st ps:P39 ?pos. ?pos wdt:P31/wdt:P279* wd:Q83307.
 OPTIONAL{?st pq:P582 ?end} FILTER(!BOUND(?end) || ?end > "2018-01-01"^^xsd:dateTime) ?p wikibase:sitelinks ?n. FILTER(?n>=15)
 ?p rdfs:label ?l. FILTER(LANG(?l)="en") }""",
 'us congress':"""SELECT DISTINCT ?l WHERE { VALUES ?pos {wd:Q13218630 wd:Q4416090} ?p p:P39 ?st. ?st ps:P39 ?pos.
 ?st pq:P580 ?s. FILTER(?s > "2012-01-01"^^xsd:dateTime) ?p rdfs:label ?l. FILTER(LANG(?l)="en") }""",
 'us governors':"""SELECT DISTINCT ?l WHERE { ?p p:P39 ?st. ?st ps:P39 ?pos. ?pos wdt:P279 wd:Q889821.
 OPTIONAL{?st pq:P582 ?end} FILTER(!BOUND(?end) || ?end > "2012-01-01"^^xsd:dateTime) ?p rdfs:label ?l. FILTER(LANG(?l)="en") }""",
 'mayors (cities >1M)':"""SELECT DISTINCT ?l WHERE { ?c wdt:P1082 ?pop. FILTER(?pop>1000000) ?c wdt:P6 ?p. ?p wdt:P31 wd:Q5; rdfs:label ?l. FILTER(LANG(?l)="en") }""",
 'CEOs of large companies':"""SELECT DISTINCT ?l WHERE { ?co wdt:P169 ?p. ?co wdt:P2139|wdt:P2403|wdt:P2226 ?v. FILTER(?v > 10000000000)
 ?p wdt:P31 wd:Q5; rdfs:label ?l. FILTER(LANG(?l)="en") }""",
 'celebrities (>=80 sitelinks, living)':"""SELECT ?l WHERE { ?p wikibase:sitelinks ?n. FILTER(?n>=110) ?p wdt:P31 wd:Q5. ?p rdfs:label ?l. FILTER(LANG(?l)="en") } LIMIT 8000""",
}
# very well-known figures: aliases + bare surnames allowed (curated, not generated)
CURATED=['Trump','Donald Trump','Musk','Elon Musk','Putin','Vladimir Putin','Zelensky','Zelenskyy','Volodymyr Zelensky','Biden','Joe Biden','Newsom','Gavin Newsom','AOC','Alexandria Ocasio-Cortez','Kim Jong Un','Xi Jinping','Kamala Harris','Netanyahu','Modi','Narendra Modi','Pope Francis','Pope Leo XIV','Taylor Swift']
names=set();failed=False
for k,s in QS.items():
  r=q(s);print(f'{k}: {len(r)}',file=sys.stderr);failed|=not r
  for b in r:
    l=b['l']['value'].strip()
    if 4<=len(l)<=60 and ' ' in l and not re.search(r'\d|^Q\d',l): names.add(l)
  time.sleep(2)
names|=set(CURATED)
if len(names)<1500: sys.exit('too few names, keeping previous file')
out=os.path.join(os.path.dirname(__file__),'..','data','public_figures.txt')
if failed and os.path.exists(out): names|={l.strip() for l in open(out) if l.strip() and l[0]!='#'}  # a timed-out category keeps its previous names
open(out,'w').write('# generated by .github/public_figures.py from Wikidata (CC0); names only, keyword use only\n'+'\n'.join(sorted(names,key=str.lower))+'\n')
print(len(names),'names',file=sys.stderr)
